def rolling_maze_path(maze,start,destination):
    rows,cols=len(maze),len(maze[0])
    stack=[tuple(start)]
    seen=set(stack)
    goal=tuple(destination)
    while stack:
        row,col=stack.pop()
        if (row,col)==goal:
            return True
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            r,c=row,col
            while 0<=r+dr<rows and 0<=c+dc<cols and maze[r+dr][c+dc]==0:
                r,c=r+dr,c+dc
            if (r,c) not in seen:
                seen.add((r,c))
                stack.append((r,c))
    return False

